i32  // error union type",\n        "comptime_int / comptime_float  // compile-time types"\n      ],\n      "Functions": [\n        "fn add(a: i32, b: i32) i32 { return a+b }  // function",\n        "fn print(msg: []const u8) void { }  // void function",\n        "pub fn publicFunc() void {}  // public export"\n      ],\n      "Control Flow": [\n        "if (cond) {} else {}  // conditional",\n        "switch (x) { 1=>{}, else=>{} }  // switch",\n        "for (items) |item| {}  // iterate",\n        "for (items, 0..) |item, i| {}  // with index",\n        "while (cond) : (continueExpr) {}  // while",\n        "break / continue  // loop control",\n        "defer { cleanup() }  // scope exit reverse order",\n        "errdefer { rollback() }  // only on error"\n      ],\n      "Struct & Enum & Union": [\n        "const Point = struct { x: i32, y: i32 }  // struct",\n        "const Color = enum { red, green, blue }  // enum",\n        "const R = union(enum) { ok: i32, err: Error }  // tagged union"\n      ],\n      "Error Handling": [\n        "const Error = error { NotFound }  // error set",\n        "fn risky() Error!i32 { return Error.NotFound }  // error union return",\n        "try risky()  // unwrap or return error",\n        "risky() catch 0  // catch with default",\n        "const val = x orelse 0  // optional default"\n      ],\n      "Comptime & Memory": [\n        "comptime { }  // compile-time block",\n        "inline for / inline while  // loop unrolling",\n        "const alloc = std.heap.page_allocator  // allocator",\n        "const p = try alloc.alloc(i32, 10)  // allocate slice",\n        "alloc.free(p)  // free memory"\n      ],\n      "Standard Library": [\n        "std.debug.print(\\"val={}\\\\n\\", .{v})  // print",\n        "std.mem.eql(u8, \\"a\\", \\"a\\")  // byte equality",\n        "std.ArrayList(i32).init(alloc)  // dynamic array",\n        "std.AutoHashMap(u32, []const u8).init(alloc)  // hash map",\n        "test \\"desc\\" { try expect(1+1==2) }  // test block"\n      ]\n    },\n    "bootstrap": {\n      "Grid & Layout": [\n        ".container  // fixed-width container (responsive max-width per breakpoint)",\n        ".container-fluid  // full-width container (always 100%)",\n        ".container-{breakpoint}  // 100% wide until specified breakpoint (sm, md, lg, xl, xxl)",\n        ".row  // flexbox row wrapper for columns",\n        ".col  // equal-width column (auto-layout)",\n        ".col-{size}  // column spanning {size} of 12 units (1-12)",\n        ".col-{breakpoint}-{size}  // responsive column at breakpoint and up",\n        ".col-{breakpoint}-auto  // auto-width column at breakpoint",\n        ".row-cols-{n}  // grid where each row has n equal columns (1-6)",\n        ".g-{size} / .gx-{size} / .gy-{size}  // gutter spacing (0-5)",\n        ".order-{n} / .order-first / .order-last  // flexbox column ordering",\n        ".offset-{breakpoint}-{size}  // offset column by n units",\n        ".align-items-{start|center|end|baseline|stretch}  // vertical alignment on row",\n        ".justify-content-{start|center|end|around|between|evenly}  // horizontal alignment"\n      ],\n      "Components": [\n        ".btn .btn-{color}  // button with contextual color (primary, secondary, success, etc.)",\n        ".btn-outline-{color}  // outline button variant",\n        ".btn-lg / .btn-sm  // button sizing",\n        ".btn-group  // group buttons together horizontally",\n        ".card .card-body  // flexible content container",\n        ".card-header / .card-footer  // card sections",\n        ".card-img-top / .card-img-bottom  // card images",\n        ".navbar .navbar-brand .navbar-nav  // responsive navigation header",\n        ".navbar-expand-{breakpoint}  // responsive navbar breakpoint",\n        ".navbar-light / .navbar-dark  // navbar color scheme",\n        ".nav-tabs / .nav-pills  // navigation styles",\n        ".nav-fill / .nav-justified  // nav width distribution",\n        ".badge .bg-{color}  // small count/label component",\n        ".badge.rounded-pill  // pill-shaped badge",\n        ".alert .alert-{color}  // contextual feedback message",\n        ".alert-dismissible  // dismissible alert with close button",\n        ".progress  // progress bar container",\n        ".progress-bar  // progress bar fill",\n        ".spinner-border / .spinner-grow  // loading spinners",\n        ".list-group .list-group-item  // display series of content",\n        ".list-group-flush  // borderless list group",\n        ".modal .modal-dialog .modal-content  // dialog box",\n        ".modal-sm / .modal-lg / .modal-xl  // modal sizes",\n        ".modal-dialog-centered  // vertically centered modal",\n        ".dropdown / .dropdown-menu / .dropdown-item  // toggleable dropdown",\n        ".accordion .accordion-item  // collapsible content sections",\n        ".carousel .carousel-inner .carousel-item  // slideshow component",\n        ".toast  // lightweight notification",\n        ".tooltip  // tooltip (requires Popper)",\n        ".popover  // popover with header/body (requires Popper)",\n        ".offcanvas  // off-canvas sidebar panel"\n      ],\n      "Forms": [\n        ".form-control  // text input, textarea, select styling",\n        ".form-control-lg / .form-control-sm  // input sizing",\n        ".form-select  // custom select dropdown",\n        ".form-check / .form-check-input / .form-check-label  // checkboxes and radios",\n        ".form-switch  // toggle switch",\n        ".form-check-inline  // inline check/radio",\n        ".form-range  // range slider",\n        ".form-floating  // floating label input",\n        ".input-group / .input-group-text  // extend form controls with addons",\n        ".form-label  // form label styling",\n        ".form-text  // help text below input",\n        ".was-validated / .is-valid / .is-invalid  // validation states",\n        ".valid-feedback / .invalid-feedback  // validation messages",\n        ".valid-tooltip / .invalid-tooltip  // tooltip validation",\n        "disabled  // attribute to disable input",\n        "readonly  // attribute for read-only input"\n      ],\n      "Utilities": [\n        ".d-{value}  // display property (none, block, inline, flex, grid, etc.)",\n        ".d-{breakpoint}-{value}  // responsive display",\n        ".flex-row / .flex-column  // flex direction",\n        ".flex-wrap / .flex-nowrap  // flex wrapping",\n        ".flex-fill  // flex item fills available space",\n        ".flex-grow-1 / .flex-shrink-1  // grow/shrink ability",\n        ".gap-{size}  // gap between flex items (0-5)",\n        ".m{t|b|s|e|x|y}-{size}  // margin: top, bottom, start, end, x, y (0-5, auto)",\n        ".p{t|b|s|e|x|y}-{size}  // padding: top, bottom, start, end, x, y (0-5)",\n        ".m-{breakpoint}-{size}  // responsive margin",\n        ".text-{start|center|end}  // text alignment",\n        ".text-{breakpoint}-{alignment}  // responsive text alignment",\n        ".fw-{bold|normal|light}  // font weight",\n        ".fst-italic  // italic text",\n        ".text-{color}  // text color (primary, secondary, muted, etc.)",\n        ".bg-{color}  // background color",\n        ".bg-gradient  // background gradient",\n        ".border / .border-{side}  // borders",\n        ".border-{color}  // border color",\n        ".rounded / .rounded-{size} / .rounded-pill / .rounded-circle  // border radius",\n        ".shadow / .shadow-sm / .shadow-lg  // box shadows",\n        ".w-{25|50|75|100|auto}  // width percentage",\n        ".h-{25|50|75|100|auto}  // height percentage",\n        ".overflow-{auto|hidden|visible|scroll}  // overflow behavior",\n        ".position-{static|relative|absolute|fixed|sticky}  // positioning",\n        ".fixed-top / .fixed-bottom / .sticky-top  // fixed/sticky positioning",\n        ".visually-hidden  // hide visually but accessible to screen readers",\n        ".visually-hidden-focusable  // hidden until focused",\n        ".text-truncate  // text ellipsis overflow",\n        ".text-break  // break long words"\n      ]\n    },\n    "django": {\n      "Management Commands": [\n        "django-admin startproject mysite  // create new Django project",\n        "python manage.py startapp blog  // create new app within project",\n        "python manage.py runserver  // start development server",\n        "python manage.py makemigrations  // create migration files from model changes",\n        "python manage.py migrate  // apply database migrations",\n        "python manage.py showmigrations  // list all migrations and status",\n        "python manage.py sqlmigrate app 0001  // view SQL for a migration",\n        "python manage.py createsuperuser  // create admin user",\n        "python manage.py shell  // open Django shell (IPython if available)",\n        "python manage.py collectstatic  // gather static files into STATIC_ROOT",\n        "python manage.py test  // run tests",\n        "python manage.py dumpdata app.Model  // export data as JSON fixture",\n        "python manage.py loaddata fixture.json  // import data from fixture",\n        "python manage.py changepassword username  // change user password"\n      ],\n      "Models & ORM": [\n        "models.CharField(max_length=100)  // string field with max length",\n        "models.TextField()  // large text field (no max length)",\n        "models.IntegerField()  // integer field",\n        "models.FloatField()  // floating-point number",\n        "models.BooleanField()  // true/false field",\n        "models.DateField() / models.DateTimeField()  // date and datetime fields",\n        "models.EmailField()  // email validator field",\n        "models.URLField()  // URL validator field",\n        "models.FileField(upload_to=\'files/\')  // file upload field",\n        "models.ImageField(upload_to=\'images/\')  // image upload field",\n        "models.ForeignKey(Model, on_delete=models.CASCADE)  // many-to-one relationship",\n        "models.ManyToManyField(Model)  // many-to-many relationship",\n        "models.OneToOneField(Model, on_delete=models.CASCADE)  // one-to-one relationship",\n        "Model.objects.all()  // get all objects",\n        "Model.objects.filter(field=value)  // filter objects",\n        "Model.objects.exclude(field=value)  // exclude matching objects",\n        "Model.objects.get(field=value)  // get single object (raises DoesNotExist)",\n        "Model.objects.create(field=value)  // create and save new object",\n        "Model.objects.order_by(\'field\')  // order ascending (prefix - for desc)",\n        "Model.objects.values(\'field\')  // return dicts instead of model instances",\n        "Model.objects.select_related(\'fk\')  // join ForeignKey (SQL JOIN)",\n        "Model.objects.prefetch_related(\'m2m\')  // prefetch ManyToMany (separate query)",\n        "Model.objects.annotate(count=Count(\'related\'))  // add computed fields",\n        "Model.objects.aggregate(Avg(\'field\'))  // compute aggregate over queryset",\n        "Model.objects.count()  // number of objects in queryset",\n        "Model.objects.exists()  // check if any objects exist",\n        "field__contains=\'value\'  // SQL LIKE containment",\n        "field__icontains=\'value\'  // case-insensitive contains",\n        "field__in=[1,2,3]  // IN list filter",\n        "field__gt=5 / field__gte=5  // greater than (or equal)",\n        "field__lt=5 / field__lte=5  // less than (or equal)",\n        "field__startswith=\'pre\'  // starts with",\n        "field__range=(start, end)  // between range (inclusive)",\n        "field__date=\'2024-01-15\'  // date comparison on datetime field",\n        "field__isnull=True  // IS NULL filter"\n      ],\n      "Views & URLs": [\n        "from django.http import HttpResponse  // basic HTTP response",\n        "from django.shortcuts import render  // render template with context",\n        "from django.shortcuts import redirect  // redirect to URL",\n        "from django.shortcuts import get_object_or_404  // get or 404 shortcut",\n        "from django.http import JsonResponse  // JSON response",\n        "path(\'route/\', view, name=\'name\')  // URL pattern",\n        "path(\'<int:id>/\', view, name=\'detail\')  // URL with int parameter",\n        "path(\'<slug:slug>/\', view, name=\'slug\')  // URL with slug parameter",\n        "re_path(r\'^regex/$\', view)  // regex URL pattern",\n        "include(\'app.urls\')  // include other URLconfs",\n        "from django.views.generic import ListView  // generic list view",\n        "from django.views.generic import DetailView  // generic detail view",\n        "from django.views.generic.edit import CreateView  // generic create view",\n        "from django.views.generic.edit import UpdateView  // generic update view",\n        "from django.views.generic.edit import DeleteView  // generic delete view",\n        "from django.contrib.auth.decorators import login_required  // login decorator",\n        "from django.contrib.auth.mixins import LoginRequiredMixin  // login mixin for CBV"\n      ],\n      "Templates": [\n        "{{ variable }}  // output variable value",\n        "{% tag %}  // execute template tag",\n        "{% for item in list %} ... {% endfor %}  // loop over iterable",\n        "{% if condition %} ... {% endif %}  // conditional block",\n        "{% block name %} ... {% endblock %}  // definable block for inheritance",\n        "{% extends \'base.html\' %}  // extend parent template",\n        "{% include \'partial.html\' %}  // include another template",\n        "{% url \'view-name\' arg %}  // reverse URL by name",\n        "{% static \'path/to/file\' %}  // static file URL",\n        "{% csrf_token %}  // CSRF protection token",\n        "{% load static %}  // load template tag library",\n        "value|default:\'fallback\'  // default filter if value is falsy",\n        "value|date:\'F j, Y\'  // format date",\n        "value|length  // length of sequence",\n        "value|upper / value|lower  // case conversion",\n        "value|truncatechars:100  // truncate to N chars",\n        "value|safe  // mark as safe HTML (no escaping)",\n        "value|linebreaks  // convert newlines to <br>",\n        "value|pluralize  // pluralize suffix (adds \'s\')"\n      ]\n    },\n    "flask": {\n      "Core": [\n        "from flask import Flask  // import Flask class",\n        "app = Flask(__name__)  // create Flask application instance",\n        "@app.route(\'/\')  // register route with decorator",\n        "@app.route(\'/user/<username>\')  // route with variable",\n        "@app.route(\'/post/<int:post_id>\')  // route with typed variable",\n        "@app.route(\'/login\', methods=[\'GET\', \'POST\'])  // route with HTTP methods",\n        "app.run(debug=True)  // run development server",\n        "app.run(host=\'0.0.0.0\', port=8000)  // run on specific host/port",\n        "if __name__ == \'__main__\': app.run()  // entry point guard",\n        "from flask import request  // request object (incoming data)",\n        "request.method  // HTTP method (GET, POST, etc.)",\n        "request.args.get(\'key\')  // query string parameter",\n        "request.form[\'key\']  // form data (POST body)",\n        "request.get_json()  // parse JSON request body",\n        "request.files[\'file\']  // uploaded file",\n        "request.headers.get(\'Header-Name\')  // request header",\n        "request.cookies.get(\'key\')  // cookie value",\n        "request.url  // full request URL",\n        "from flask import jsonify  // JSON response helper",\n        "jsonify({\'key\': \'value\'})  // return JSON response",\n        "from flask import redirect  // redirect helper",\n        "redirect(url_for(\'view\'))  // redirect to endpoint",\n        "from flask import abort  // abort with error code",\n        "abort(404)  // return 404 error",\n        "from flask import url_for  // URL generation",\n        "url_for(\'view_name\', arg=value)  // generate URL for endpoint",\n        "url_for(\'static\', filename=\'style.css\')  // static file URL"\n      ],\n      "Blueprints": [\n        "from flask import Blueprint  // import Blueprint",\n        "bp = Blueprint(\'name\', __name__)  // create blueprint",\n        "bp = Blueprint(\'auth\', __name__, url_prefix=\'/auth\')  // blueprint with prefix",\n        "@bp.route(\'/\')  // route on blueprint",\n        "app.register_blueprint(bp)  // register blueprint on app",\n        "app.register_blueprint(bp, url_prefix=\'/prefix\')  // register with prefix",\n        "url_for(\'blueprint.view\')  // URL for blueprint endpoint"\n      ],\n      "Jinja2 Templates": [\n        "{{ variable }}  // output expression value",\n        "{% for item in list %} ... {% endfor %}  // loop",\n        "{% if cond %} ... {% endif %}  // conditional",\n        "{% extends \'base.html\' %}  // template inheritance",\n        "{% block name %} ... {% endblock %}  // block definition",\n        "{% include \'partial.html\' %}  // include template",\n        "url_for(\'view\')  // URL generation in templates",\n        "config[\'KEY\']  // access Flask config in template",\n        "request  // access request object in template",\n        "session  // access session object in template",\n        "g  // application context object in template",\n        "get_flashed_messages()  // flash messages",\n        "|safe  // mark as safe HTML",\n        "|capitalize / |upper / |lower / |title  // string transforms",\n        "|default(\'val\')  // default value",\n        "|length  // sequence length",\n        "|trim  // strip whitespace",\n        "|striptags  // remove HTML tags",\n        "|truncate(length)  // truncate text"\n      ],\n      "Flask-SQLAlchemy": [\n        "from flask_sqlalchemy import SQLAlchemy  // import ORM",\n        "db = SQLAlchemy(app)  // init with app",\n        "db.init_app(app)  // init after app creation (factory pattern)",\n        "class User(db.Model):  // define model class",\n        "db.Column(db.Integer, primary_key=True)  // column definition",\n        "db.Column(db.String(80), unique=True, nullable=False)  // string column",\n        "db.Column(db.DateTime, default=datetime.utcnow)  // datetime with default",\n        "db.Column(db.ForeignKey(\'user.id\'))  // foreign key column",\n        "db.relationship(\'Post\', backref=\'author\')  // relationship",\n        "db.create_all()  // create all tables",\n        "db.session.add(obj)  // add object to session",\n        "db.session.commit()  // commit transaction",\n        "db.session.delete(obj)  // delete object",\n        "Model.query.all()  // query all",\n        "Model.query.get(id)  // get by primary key",\n        "Model.query.filter_by(field=val).first()  // filter by kwargs",\n        "Model.query.filter(Model.field > val).all()  // filter with expression",\n        "Model.query.order_by(Model.field.desc())  // ordering",\n        "Model.query.paginate(page, per_page)  // pagination",\n        "Model.query.join(OtherModel)  // SQL JOIN"\n      ],\n      "Extensions": [\n        "Flask-WTF: FlaskForm, CSRF protection  // form handling",\n        "Flask-Login: LoginManager, login_user, logout_user  // user sessions",\n        "Flask-Migrate: Migrate, flask db init/migrate/upgrade  // DB migrations",\n        "Flask-Mail: Mail, Message  // email sending",\n        "Flask-Caching: Cache  // caching",\n        "Flask-CORS: CORS  // cross-origin resource sharing"\n      ]\n    },\n    "fastapi": {\n      "App Setup": [\n        "from fastapi import FastAPI  // import FastAPI",\n        "app = FastAPI(title=\'My API\', version=\'1.0.0\')  // create app instance",\n        "@app.get(\'/\')  // GET route decorator",\n        "@app.post(\'/\')  // POST route decorator",\n        "@app.put(\'/{id}\')  // PUT route decorator",\n        "@app.delete(\'/{id}\')  // DELETE route decorator",\n        "@app.patch(\'/{id}\')  // PATCH route decorator",\n        "@app.get(\'/items/{item_id}\')  // path parameter route",\n        "uvicorn main:app --reload  // run dev server",\n        "from pydantic import BaseModel  // import data validation model",\n        "class Item(BaseModel): name: str; price: float  // define model",\n        "from typing import Optional  // for optional fields",\n        "item: Item  // type hint as endpoint parameter (auto-parsed body)",\n        "from fastapi import Path, Query  // import parameter validators",\n        "Path(ge=1, le=100)  // path param with numeric validation",\n        "Query(min_length=3, max_length=50)  // query param with string validation",\n        "from fastapi import Body  // body field marker",\n        "from fastapi import Header  // header parameter",\n        "from fastapi import Cookie  // cookie parameter",\n        "from fastapi import Form  // form data (non-JSON)",\n        "from fastapi import File, UploadFile  // file upload"\n      ],\n      "Response & Status": [\n        "response_model=ItemOut  // filter/validate response data",\n        "status_code=status.HTTP_201_CREATED  // set response status",\n        "response_model_exclude_unset=True  // exclude unset fields (PATCH)",\n        "from fastapi.responses import JSONResponse  // JSON response",\n        "from fastapi.responses import HTMLResponse  // HTML response",\n        "from fastapi.responses import FileResponse  // file download",\n        "from fastapi.responses import RedirectResponse  // redirect",\n        "from fastapi.responses import StreamingResponse  // stream data",\n        "from fastapi.responses import PlainTextResponse  // plain text",\n        "from fastapi import status  // HTTP status code constants",\n        "from fastapi.exceptions import HTTPException  // raise HTTP errors",\n        "raise HTTPException(status_code=404, detail=\'Not found\')  // error",\n        "from fastapi import Depends  // dependency injection",\n        "Depends(get_db)  // inject dependency into endpoint"\n      ],\n      "Pydantic Validation": [\n        "Field(..., ge=0)  // required field with validation",\n        "Field(None, max_length=100)  // optional field with validation",\n        "Field(default=\'val\', pattern=\'^regex$\')  // default + pattern",\n        "@field_validator(\'field\')  // custom field validator (Pydantic v2)",\n        "@model_validator(mode=\'after\')  // model-level validation",\n        "field.model_dump()  // serialize to dict",\n        "field.model_dump(exclude_unset=True)  // only set fields",\n        "field.model_dump_json()  // serialize to JSON string",\n        "model.model_validate(obj)  // create from dict/object",\n        "from pydantic import EmailStr  // email validation",\n        "from pydantic import SecretStr  // secret string (hides in repr)",\n        "field.Config.from_attributes = True  // ORM mode (read from DB)"\n      ],\n      "Dependencies": [\n        "async def get_db(): yield session  // DB session dependency",\n        "Depends(get_current_user)  // auth dependency",\n        "from fastapi.security import OAuth2PasswordBearer  // OAuth2 scheme",\n        "oauth2_scheme = OAuth2PasswordBearer(tokenUrl=\'/login\')  // token URL",\n        "from fastapi.security import HTTPBearer  // HTTP Bearer scheme",\n        "from fastapi.security import APIKeyHeader  // API key in header",\n        "Security(oauth2_scheme, scopes=[\'admin\'])  // security with scopes",\n        "from fastapi import BackgroundTasks  // background tasks",\n        "BackgroundTasks.add_task(send_email, to=email)  // add task",\n        "app.dependency_overrides[dep] = mock  // override for testing"\n      ],\n      "WebSockets": [\n        "from fastapi import WebSocket  // import WebSocket",\n        "@app.websocket(\'/ws\')  // WebSocket route",\n        "websocket.accept()  // accept WebSocket connection",\n        "websocket.receive_text()  // receive text message",\n        "websocket.receive_json()  // receive JSON message",\n        "websocket.send_text(\'msg\')  // send text message",\n        "websocket.send_json({\'key\': \'val\'})  // send JSON message",\n        "websocket.close()  // close connection",\n        "from fastapi import WebSocketDisconnect  // disconnect exception"\n      ]\n    },\n    "spring": {\n      "Annotations": [\n        "@SpringBootApplication  // main Spring Boot app class",\n        "@RestController  // REST controller (convenience for @Controller + @ResponseBody)",\n        "@RequestMapping(\'/api\')  // class-level URL mapping",\n        "@GetMapping(\'/users\')  // GET mapping",\n        "@PostMapping  // POST mapping",\n        "@PutMapping(\'/{id}\')  // PUT mapping",\n        "@DeleteMapping(\'/{id}\')  // DELETE mapping",\n        "@PatchMapping(\'/{id}\')  // PATCH mapping",\n        "@PathVariable  // extract path parameter",\n        "@RequestParam  // extract query parameter",\n        "@RequestBody  // bind request body",\n        "@RequestHeader  // extract header value",\n        "@Valid / @Validated  // trigger validation",\n        "@ResponseStatus(HttpStatus.CREATED)  // set response status",\n        "@ExceptionHandler  // handle exceptions in controller",\n        "@ControllerAdvice  // global exception handler",\n        "@Autowired  // dependency injection (field/setter/constructor)",\n        "@Qualifier(\'beanName\')  // specify which bean to inject",\n        "@Primary  // preferred bean when multiple candidates",\n        "@Component/@Service/@Repository/@Controller  // stereotype annotations",\n        "@Bean  // declare a bean in @Configuration class",\n        "@Configuration  // class with @Bean definitions",\n        "@Value(\'${property}\')  // inject property value",\n        "@ConfigurationProperties(prefix=\'app\')  // type-safe config binding",\n        "@Profile(\'dev\')  // conditional bean based on active profile",\n        "@Transactional  // declarative transaction management",\n        "@Cacheable / @CacheEvict / @CachePut  // caching annotations",\n        "@Scheduled  // scheduled task execution",\n        "@Async  // asynchronous execution",\n        "@CrossOrigin  // enable CORS on controller/method"\n      ],\n      "JPA & Database": [\n        "@Entity  // JPA entity class",\n        "@Table(name = \'users\')  // table name customization",\n        "@Id @GeneratedValue(strategy = GenerationType.IDENTITY)  // auto-increment PK",\n        "@Column(name = \'email\', nullable = false, unique = true)  // column customization",\n        "@Enumerated(EnumType.STRING)  // enum mapping",\n        "@OneToMany(mappedBy = \'user\')  // one-to-many relationship",\n        "@ManyToOne(fetch = FetchType.LAZY)  // many-to-one with lazy loading",\n        "@JoinColumn(name = \'user_id\')  // foreign key column",\n        "@ManyToMany  // many-to-many relationship",\n        "@JoinTable  // join table for many-to-many",\n        "extends JpaRepository<T, ID>  // JPA repository interface",\n        "findByField(value)  // derived query: equals",\n        "findByFieldContaining(value)  // derived query: like %value%",\n        "findByFieldBetween(a, b)  // derived query: between",\n        "findByFieldGreaterThan(value)  // derived query: greater than",\n        "countByField(value)  // derived query: count",\n        "existsByField(value)  // derived query: exists",\n        "@Query(\'SELECT e FROM Entity e WHERE e.field = :param\')  // custom JPQL",\n        "@Query(value = \'SELECT * FROM table\', nativeQuery = true)  // native SQL",\n        "@Modifying @Query(\'UPDATE ...\')  // update/delete query",\n        "Pageable / Page<T>  // pagination support",\n        "Sort.by(Direction.DESC, \'field\')  // sorting",\n        "@EntityGraph(attributePaths = {\'related\'})  // eager loading"\n      ],\n      "Spring Security": [\n        "@EnableWebSecurity  // enable security configuration",\n        "@EnableMethodSecurity  // enable method-level security",\n        "SecurityFilterChain  // filter chain bean",\n        "authorizeHttpRequests(auth -> auth.anyRequest().authenticated())  // require auth",\n        "requestMatchers(\'/api/public/**\').permitAll()  // public endpoints",\n        "requestMatchers(\'/api/admin/**\').hasRole(\'ADMIN\')  // role-based access",\n        ".sessionManagement(sm -> sm.sessionCreationPolicy(STATELESS))  // stateless (JWT)",\n        ".csrf(AbstractHttpConfigurer::disable)  // disable CSRF (REST API)",\n        "PasswordEncoder / BCryptPasswordEncoder  // password hashing",\n        "UserDetailsService  // user details lookup",\n        "DaoAuthenticationProvider  // auth provider",\n        "@PreAuthorize(\'hasRole(\'\'ADMIN\'\')\')  // method security check",\n        "@PostAuthorize(\'returnObject.owner == authentication.name\')  // post-invocation check",\n        "UsernamePasswordAuthenticationFilter  // form login filter",\n        "OncePerRequestFilter  // base class for custom filters",\n        "SecurityContextHolder.getContext().getAuthentication()  // current auth"\n      ],\n      "Testing": [\n        "@SpringBootTest  // integration test",\n        "@WebMvcTest(Controller.class)  // controller slice test",\n        "@DataJpaTest  // repository slice test",\n        "@MockBean  // mock a bean",\n        "MockMvc  // mock HTTP requests (controller test)",\n        "mockMvc.perform(get(\'/api/users\')).andExpect(status().isOk())  // GET test",\n        "mockMvc.perform(post(\'/api/users\').content(json).contentType(JSON))  // POST test",\n        "TestRestTemplate  // REST template for integration tests",\n        "ResponseEntity<T>  // HTTP response wrapper",\n        "@Testcontainers  // container-based integration tests",\n        "assertThat(value).isEqualTo(expected)  // AssertJ assertion",\n        "@BeforeEach / @AfterEach  // setup/teardown"\n      ]\n    },\n    "webassembly": {\n      "Modules & Exports": [\n        "(module)  // root of every WAT module",\n        "(export \\"name\\" (func $internal))  // export a function",\n        "(export \\"mem\\" (memory $mem))  // export memory",\n        "(import \\"env\\" \\"print\\" (func $print (param i32)))  // import a function",\n        "(import \\"js\\" \\"mem\\" (memory 1))  // import memory",\n        "(import \\"env\\" \\"offset\\" (global $off i32))  // import a global",\n        "(export \\"add\\" (func $add))  (func $add (param i32 i32) (result i32) local.get 0 local.get 1 i32.add)  // full example"\n      ],\n      "Functions & Locals": [\n        "(func $name (param $p i32) (result i32) ...)  // function with param and result",\n        "(local $v i32)  // declare a local variable (zero-initialized)",\n        "local.get $v  // push local value onto stack",\n        "local.set $v  // pop stack into local",\n        "local.tee $v  // set local and keep value on stack",\n        "call $name  // call a function",\n        "return  // return from function",\n        "call_indirect (result i32)  // call function from table by index"\n      ],\n      "Numeric Instructions": [\n        "i32.const 42  // push 32-bit integer constant",\n        "i64.const 100  // push 64-bit integer constant",\n        "f32.const 3.14  // push 32-bit float constant",\n        "f64.const 2.71  // push 64-bit float constant",\n        "i32.add / i32.sub / i32.mul / i32.div_s / i32.rem_s  // integer arithmetic",\n        "i32.and / i32.or / i32.xor / i32.shl / i32.shr_s  // bitwise operations",\n        "i32.eq / i32.ne / i32.lt_s / i32.gt_s / i32.le_s / i32.ge_s  // comparisons",\n        "f32.add / f32.sub / f32.mul / f32.div  // float arithmetic",\n        "i32.trunc_f64_s / f64.convert_i32_s  // type conversion"\n      ],\n      "Control Flow": [\n        "(block $lbl ... end)  // define a block with exit label",\n        "(loop $lbl ... end)  // define a loop (branches go back to start)",\n        "(if (result i32) ... else ... end)  // if/else with result type",\n        "br $lbl  // branch to label (exit block or restart loop)",\n        "br_if $lbl  // branch if top of stack is non-zero",\n        "br_table $a $b $c $default  // computed branch (switch)",\n        "unreachable  // trap (should never be reached)",\n        "nop  // no operation"\n      ],\n      "Memory": [\n        "(memory $mem 1)  // declare memory with 1 initial page (64KiB)",\n        "(memory $mem 1 256)  // memory with max 256 pages (16MiB)",\n        "i32.load  // load i32 from memory (pop addr, push value)",\n        "i32.store  // store i32 to memory (pop addr, pop value)",\n        "i32.load8_s / i32.load8_u  // load signed/unsigned byte",\n        "i32.store8 / i32.store16  // store byte/16-bit",\n        "memory.grow  // grow memory by N pages (returns previous size or -1)",\n        "memory.size  // get current memory size in pages",\n        "memory.copy  // bulk copy (memcpy): dst src len",\n        "memory.fill  // bulk fill (memset): addr val len"\n      ],\n      "Tables & Globals": [\n        "(table $tbl 10 funcref)  // declare a function table with 10 slots",\n        "(elem (i32.const 0) $func1 $func2)  // pre-fill table entries",\n        "table.get $tbl  // get function reference from table",\n        "table.set $tbl  // set function reference in table",\n        "table.size $tbl  // get table size",\n        "table.grow $tbl  // grow table",\n        "(global $g (mut i32) (i32.const 0))  // mutable global variable",\n        "global.get $g  // read global",\n        "global.set $g  // write mutable global"\n      ],\n      "WASI & Running": [\n        "# Run WAT file directly with wasmtime",\n        "wasmtime mymodule.wat  // compile and run on the fly",\n        "wasmtime mymodule.wasm arg1 arg2  // run compiled Wasm with args",\n        "wasmtime --dir=. myapp.wasm  // grant filesystem access",\n        "wasmtime --env KEY=VALUE myapp.wasm  // pass env vars",\n        "wasmtime --fuel 100000 myapp.wasm  // limit execution with fuel",\n        "wasmtime --max-memory=10M myapp.wasm  // limit memory",\n        "# Tools",\n        "wat2wasm input.wat -o output.wasm  // compile WAT to Wasm binary",\n        "wasm2wat output.wasm -o decompiled.wat  // decompile Wasm to WAT",\n        "wasm-validate module.wasm  // check if valid",\n        "wasm-opt -Oz input.wasm -o output.wasm  // optimize for size",\n        "wasm-strip module.wasm -o stripped.wasm  // remove debug sections"\n      ],\n      "JS Interop": [\n        "WebAssembly.instantiate(bytes, imports)  // compile + instantiate",\n        "WebAssembly.instantiateStreaming(fetch(\'m.wasm\'), imports)  // streaming version",\n        "instance.exports.funcName(args)  // call exported Wasm function",\n        "new WebAssembly.Memory({initial:1, maximum:256})  // create shared memory",\n        "new WebAssembly.Table({initial:10, element:\'funcref\'})  // create table",\n        "WebAssembly.compile(bytes)  // compile only (no instantiate)",\n        "WebAssembly.validate(bytes)  // check bytes are valid Wasm"\n      ],\n      "Toolchains": [\n        "# C/C++ with Emscripten",\n        "emcc -O3 -s WASM=1 -s EXPORTED_FUNCTIONS=\'[\\"_add\\"]\' -o out.js input.c",\n        "# Rust with wasm-pack",\n        "wasm-pack build --target web  // browser target",\n        "wasm-pack build --target nodejs  // Node.js target",\n        "# AssemblyScript",\n        "npx asc assembly/index.ts -o build.wasm --optimize",\n        "# Go with TinyGo",\n        "tinygo build -o app.wasm -target=wasi main.go",\n        "# Zig",\n        "zig build-exe main.zig -target wasm32-wasi -O ReleaseSmall"\n      ]\n    },\n    "assembly": {\n      "NASM Syntax & Directives": [\n        "section .data  // initialized data section (constants, strings, arrays)",\n        "section .bss   // uninitialized data section (reserve space)",\n        "section .text  // code section (executable instructions)",\n        "global _start  // make _start visible to linker (ELF entry point)",\n        "extern printf  // declare external symbol from C library",\n        "db 0xFF  // define byte (8 bits)",\n        "dw 0xABCD  // define word (16 bits)",\n        "dd 0xDEADBEEF  // define dword (32 bits)",\n        "dq 0x1234567890ABCDEF  // define qword (64 bits)",\n        "times 64 db 0  // repeat directive: reserve 64 zero bytes",\n        "equ  // define constant: SYS_EXIT equ 60",\n        "$  // current address (used for string length: len equ $ - msg)",\n        "resb 256  // reserve 256 bytes in .bss",\n        "align 16  // align next instruction/data to 16-byte boundary",\n        "default rel  // use RIP-relative addressing by default"\n      ],\n      "Registers": [\n        "rax  // accumulator: syscall number, return value, arithmetic",\n        "rbx  // base register (callee-saved)",\n        "rcx  // counter: loop count, shift amount (caller-saved)",\n        "rdx  // data register: 3rd syscall arg, multiply/divide (caller-saved)",\n        "rsi  // source index: 2nd syscall arg, string ops (caller-saved)",\n        "rdi  // destination index: 1st syscall arg, string ops (caller-saved)",\n        "rbp  // base pointer: stack frame reference (callee-saved)",\n        "rsp  // stack pointer: points to top of stack",\n        "r8-r15  // extended registers: r8 (5th arg), r9 (6th arg)",\n        "eax / ax / al  // 32/16/8-bit subregister of rax (zero-extends on write)",\n        "xmm0-xmm15  // 128-bit SSE/AVX registers (floating-point & SIMD)",\n        "ymm0-ymm15  // 256-bit AVX registers (float/double/int SIMD)",\n        "rflags  // status flags: CF, PF, AF, ZF, SF, OF, IF, DF",\n        "rip  // instruction pointer (read-only, used for RIP-relative addr)"\n      ],\n      "Instructions": [\n        "mov rax, rbx  // copy rbx into rax (register to register)",\n        "mov rax, [rbx]  // load from memory at address in rbx",\n        "mov [rdi], rax  // store rax to memory at address in rdi",\n        "lea rbx, [rax+rcx*4]  // load effective address (no memory access)",\n        "add rax, rbx  // rax = rax + rbx",\n        "sub rax, rbx  // rax = rax - rbx",\n        "inc rax / dec rax  // increment/decrement by 1",\n        "mul rbx  // unsigned multiply: rdx:rax = rax * rbx",\n        "div rcx  // unsigned divide: rax=quotient, rdx=remainder",\n        "imul rax, rbx, 10  // signed multiply: rax = rbx * 10",\n        "and rax, rbx  // bitwise AND",\n        "or  rax, rbx  // bitwise OR",\n        "xor rax, rbx  // bitwise XOR (xor same reg = zero idiom)",\n        "not rax  // bitwise NOT (flip all bits)",\n        "shl rax, cl  // shift left by cl bits (multiply by 2^cl)",\n        "shr rax, cl  // shift right by cl bits (unsigned divide by 2^cl)",\n        "sar rax, cl  // arithmetic shift right (preserves sign bit)",\n        "rol rax, cl  // rotate left through all bits",\n        "ror rax, cl  // rotate right through all bits"\n      ],\n      "Control Flow": [\n        "jmp label  // unconditional jump to label",\n        "je / jne  // jump if equal / not equal (ZF=1 / ZF=0)",\n        "jg / jl / jge / jle  // signed greater/less (SF, OF, ZF flags)",\n        "ja / jb / jae / jbe  // unsigned above/below (CF, ZF flags)",\n        "jo / js / jp / jc  // overflow, sign, parity, carry",\n        "cmp rax, rbx  // compare: sets flags (like sub without store)",\n        "test rax, rbx  // bitwise AND that sets flags (like and without store)",\n        "loop label  // dec rcx; jump if rcx != 0",\n        "call label  // push return address, jump to procedure",\n        "ret  // pop return address, jump back",\n        "cmovg rax, rbx  // conditional move: rax=rbx if greater (avoids branch)",\n        "sete al  // set byte to 1 if equal, else 0"\n      ],\n      "Stack & Procedures": [\n        "push rax  // decrement rsp by 8, store rax at [rsp]",\n        "pop rax  // load rax from [rsp], increment rsp by 8",\n        "push rbp  // save base pointer (prologue start)",\n        "mov rbp, rsp  // set stack frame base",\n        "sub rsp, 32  // allocate 32 bytes for local variables",\n        "leave  // restore rsp and pop rbp (shortcut for mov rsp,rbp; pop rbp)",\n        "syscall  // invoke Linux kernel: rax=syscall#, args in rdi,rsi,rdx,r10,r8,r9",\n        "extern printf  // call C library function (link with -lc)",\n        "global main  // entry point when using libc (gcc -no-pie link)"\n      ],\n      "System Calls (Linux x64)": [\n        "mov rax, 0 ; sys_read  // read from file descriptor: rdi=fd, rsi=buf, rdx=count",\n        "mov rax, 1 ; sys_write  // write to fd: rdi=fd, rsi=buf, rdx=count",\n        "mov rax, 2 ; sys_open  // open file: rdi=path, rsi=flags, rdx=mode",\n        "mov rax, 3 ; sys_close  // close fd: rdi=fd",\n        "mov rax, 9 ; sys_mmap  // mmap: rdi=addr, rsi=len, rdx=prot, r10=flags, r8=fd, r9=off",\n        "mov rax, 12 ; sys_brk  // change heap: rdi=new_break (0 = get current)",\n        "mov rax, 60 ; sys_exit  // exit: rdi=exit_code",\n        "syscall  // invoke kernel (clobbers rcx and r11)"\n      ]\n    },\n    "scala": {\n      "Variables & Types": [\n        "val x = 5  // immutable read-only reference",\n        "var y = 5  // mutable variable",\n        "val name: String = \\"Scala\\"  // explicit type annotation",\n        "val nums = List(1, 2, 3)  // type inference",\n        "val nullable: String? = null  // nullable type (Scala 3)",\n        "lazy val expensive = compute()  // lazy initialization",\n        "val z: Byte = 127  // explicit byte type",\n        "val pi = 3.14159  // inferred Double"\n      ],\n      "Functions": [\n        "def add(a: Int, b: Int): Int = a + b  // method declaration",\n        "def greet(name: String) = s\\"Hello $name\\"  // expression body, string interpolation",\n        "def applyTwice(f: Int => Int, x: Int) = f(f(x))  // higher-order function",\n        "(x: Int) => x * 2  // anonymous function/lambda",\n        "_ * 2  // short lambda (placeholder syntax)",\n        "def sum(a: Int)(b: Int) = a + b  // curried function",\n        "def addFive = add(5) _  // partially applied function",\n        "@tailrec def fact(n: Int, acc: Int = 1): Int = ...  // tail recursion"\n      ],\n      "Control Flow": [\n        "if (x > 0) \\"pos\\" else \\"neg\\"  // if expression",\n        "x match { case 1 => \\"one\\"; case _ => \\"other\\" }  // pattern matching",\n        "for (n <- List(1,2,3)) println(n)  // for loop",\n        "for (n <- 1 to 10 if n % 2 == 0) yield n * 2  // for-comprehension",\n        "while (i < 10) { i += 1 }  // while loop",\n        "try { \\"42\\".toInt } catch { case e: Exception => 0 }  // try-catch expression"\n      ],\n      "Collections": [\n        "List(1, 2, 3)  // immutable linked list",\n        "Vector(1, 2, 3)  // indexed sequence",\n        "Set(1, 2, 3)  // immutable set",\n        "Map(\\"a\\" -> 1, \\"b\\" -> 2)  // immutable map",\n        "Seq(1, 2, 3)  // ordered sequence trait",\n        "Range(1, 10, 2)  // numeric range",\n        "nums.map(_ * 2)  // transform each element",\n        "nums.filter(_ > 0)  // keep matching elements",\n        "nums.flatMap(x => List(x, -x))  // map then flatten",\n        "nums.foldLeft(0)(_ + _)  // left fold with initial value",\n        "nums.reduce(_ + _)  // reduce without initial",\n        "nums.groupBy(_ % 2)  // partition into groups",\n        "Option(42).getOrElse(0)  // optional value"\n      ],\n      "OOP": [\n        "class Person(val name: String, var age: Int)  // class with constructor",\n        "object Config { val url = \\"...\\" }  // singleton object",\n        "object Math { def apply(x: Int) = x * 2 }  // companion object with apply",\n        "trait Showable { def show: String }  // trait declaration",\n        "case class User(id: Int, name: String)  // case class (immutable, value semantics)",\n        "sealed trait Shape  // sealed hierarchy (exhaustive matching)",\n        "class Dog extends Animal with Pet  // class with mixins",\n        "u1.copy(name = \\"Bob\\")  // case class copy with modifications"\n      ],\n      "Pattern Matching": [\n        "x match { case 0 => \\"zero\\"; case _ => \\"non-zero\\" }  // basic match",\n        "case class Point(x: Int, y: Int)  // case class for destructuring",\n        "case Email(user, domain) => ...  // extractor pattern",\n        "case List(a, b, _*) => ...  // sequence pattern",\n        "case n: Int if n > 0 => ...  // typed pattern with guard",\n        "try { ... } catch { case e: IOException => ... }  // exception pattern"\n      ],\n      "Functional": [\n        "Option(42).map(_ * 2).filter(_ > 50)  // monadic chaining",\n        "for { x <- optA; y <- optB } yield x + y  // for-comprehension on Options",\n        "List(1,2,3).flatMap(x => List(x, -x))  // flatMap for collections",\n        "Future { 42 }.map(_ * 2)  // asynchronous computation",\n        "val Right(result) = parse(input)  // Either destructuring"\n      ],\n      "Scala 3": [\n        "extension (n: Int) def isEven = n % 2 == 0  // extension method",\n        "type Name = String  // type alias",\n        "val x: Int | String = 42  // union type",\n        "given intOrd: Ord[Int] with ...  // given instance",\n        "def max[T](a: T, b: T)(using Ord[T]) = ...  // using clause",\n        "@main def run() = println(\\"Hello\\")  // top-level main",\n        "enum Color { case Red, Green, Blue }  // enum type"\n      ],\n      "Build Tools": [\n        "sbt compile  // compile project",\n        "sbt run  // run main class",\n        "sbt test  // run tests",\n        "sbt console  // start REPL with project dependencies",\n        "scala-cli run script.scala  // run script with Scala CLI",\n        "scala-cli repl  // start REPL with Scala CLI"\n      ]\n    },\n    "html": {\n      "Document Structure": [\n        "<!DOCTYPE html>",\n        "<html lang=\\"en\\">...</html>",\n        "<head><meta charset=\\"UTF-8\\"><title>Title</title></head>",\n        "<body>...</body>"\n      ],\n      "Text Tags": [\n        "<h1> to <h6> — headings",\n    